// LA FORMATION MÉTIER « teacher » · voir ./types. Trois cités qui suivent le
// cycle réel du métier : préparer (la séquence, le cours vérifié, la
// différenciation), évaluer (la grille, l'évaluation alignée, les retours),
// communiquer (les parents, la classe, les données des élèves). Les
// contraintes propres au métier traversent les neuf dojos : l'équité de la
// notation, la protection des données des élèves, la vérification de chaque
// fait avant qu'il n'atteigne la classe.
import { B } from '../bilingual'
import type { Level } from '../curriculum'
import type { Enrichment } from '../enrich/types'
import type { Deepening } from '../deep/types'
import type { TradePack } from './types'

